-- WTW current canonical Drive history -> same protected D1 website read-model.
-- This is an ID-keyed projection, NOT an independent historical master.
-- It does not overwrite old stakes, names, user display-name overrides or edits.
-- Import only source-reviewed SQL generated by build-history-org-projection.mjs.
CREATE TABLE IF NOT EXISTS wtw_history_org_profiles (
  organization_id TEXT PRIMARY KEY,
  canonical_name TEXT NOT NULL,
  organization_type TEXT,
  canonical_geography TEXT,
  source_status TEXT NOT NULL,
  founded_year_source TEXT,
  origin_through_1998 TEXT,
  stakes_bloodline_anchor TEXT,
  approved_connections TEXT,
  capital_class_source TEXT,
  liquidity_profile_source TEXT,
  historical_prestige TEXT,
  momentum_1990s TEXT,
  commercial_appeal TEXT,
  peer_reputation TEXT,
  financial_vulnerability TEXT,
  continuity_constraints TEXT,
  source_authority TEXT NOT NULL,
  approval_gate TEXT NOT NULL,
  next_source_task TEXT,
  transfer_status TEXT,
  historical_year_links TEXT,
  publication_tier TEXT NOT NULL,
  source_spreadsheet_id TEXT NOT NULL,
  source_sheet_id TEXT NOT NULL,
  source_sha256 TEXT NOT NULL,
  imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_wtw_history_org_profiles_tier ON wtw_history_org_profiles(publication_tier);
CREATE TABLE IF NOT EXISTS wtw_history_org_import_manifest (
  source_sha256 TEXT PRIMARY KEY,
  source_spreadsheet_id TEXT NOT NULL,
  source_sheet_id TEXT NOT NULL,
  source_status TEXT NOT NULL,
  record_count INTEGER NOT NULL,
  approved_direction_count INTEGER NOT NULL,
  source_legacy_count INTEGER NOT NULL,
  research_only_count INTEGER NOT NULL,
  imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  note TEXT NOT NULL
);
